// demo/main.ts
var pv = document.getElementById("pv");
var $ = (id) => document.getElementById(id);
var fileInput = $("file");
var samples = $("samples");
var thumbs = $("thumbs");
var statusEl = $("status");
var playBtn = $("play");
var fileName = "";
var playing = false;
var openSeq = 0;
function setStatus(msg, error = false) {
  statusEl.textContent = msg;
  statusEl.className = error ? "error" : "";
}
function openBytes(bytes, name) {
  const t0 = performance.now();
  const legacy = bytes[0] === 208 && bytes[1] === 207;
  try {
    pv.loadPptx(bytes);
  } catch (e) {
    setStatus(`"${name}" n\xE3o abriu: ${e instanceof Error ? e.message : String(e)}`, true);
    console.error(e);
    return;
  }
  fileName = name;
  if (playing) endPlay("");
  document.title = `${name} \u2014 Viewer`;
  $("fileName").textContent = name;
  $("empty").style.display = "none";
  const n = pv.getSlideCount();
  setStatus(`"${name}": ${n} slide${n === 1 ? "" : "s"}${legacy ? " (.ppt convertido)" : ""} em ${Math.round(performance.now() - t0)} ms`);
  for (const id of ["prev", "next", "play", "full"]) $(id).disabled = n === 0;
  buildThumbs();
  updateNav();
  void pv.fontsReady().then(paintThumbs);
}
async function openFile(file) {
  const seq = ++openSeq;
  setStatus(`Abrindo "${file.name}"\u2026`);
  let bytes;
  try {
    bytes = new Uint8Array(await file.arrayBuffer());
  } catch (e) {
    if (seq === openSeq) setStatus(`"${file.name}" n\xE3o p\xF4de ser lido: ${e instanceof Error ? e.message : String(e)}`, true);
    return;
  }
  if (seq === openSeq) openBytes(bytes, file.name);
}
$("open").addEventListener("click", () => fileInput.click());
fileInput.addEventListener("change", () => {
  const f = fileInput.files?.[0];
  if (f) void openFile(f);
  fileInput.value = "";
});
var dragDepth = 0;
document.addEventListener("dragenter", (e) => {
  if (e.dataTransfer?.types.includes("Files")) {
    dragDepth++;
    document.body.classList.add("dragging");
  }
});
document.addEventListener("dragleave", () => {
  if (--dragDepth <= 0) {
    dragDepth = 0;
    document.body.classList.remove("dragging");
  }
});
document.addEventListener("dragover", (e) => e.preventDefault());
document.addEventListener("drop", (e) => {
  e.preventDefault();
  dragDepth = 0;
  document.body.classList.remove("dragging");
  const f = e.dataTransfer?.files[0];
  if (f) void openFile(f);
});
void fetch("./samples.json").then((r) => r.ok ? r.json() : []).then((list) => {
  for (const s of list) samples.add(new Option(s.name, s.url));
}).catch(() => {
  samples.style.display = "none";
});
samples.addEventListener("change", async () => {
  const url = samples.value;
  const name = samples.selectedOptions[0]?.text ?? url;
  samples.value = "";
  if (!url) return;
  const seq = ++openSeq;
  setStatus(`Baixando "${name}"\u2026`);
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const bytes = new Uint8Array(await res.arrayBuffer());
    if (seq === openSeq) openBytes(bytes, name.split("/").pop());
  } catch (e) {
    if (seq === openSeq) setStatus(`"${name}" n\xE3o baixou: ${e instanceof Error ? e.message : String(e)}`, true);
  }
});
var thumbCanvases = [];
function buildThumbs() {
  thumbs.replaceChildren();
  const probe = document.createElement("canvas");
  const ratio2 = pv.renderSlideToCanvas(0, probe, 160) ? `${probe.width} / ${probe.height}` : "16 / 9";
  thumbCanvases = [];
  for (let i2 = 0; i2 < pv.getSlideCount(); i2++) {
    const item = document.createElement("div");
    item.className = "thumb";
    item.title = `Slide ${i2 + 1}`;
    const num3 = document.createElement("span");
    num3.textContent = String(i2 + 1);
    const cv = document.createElement("canvas");
    cv.style.aspectRatio = ratio2;
    item.append(num3, cv);
    item.addEventListener("click", () => {
      pv.selectSlide(i2);
      updateNav();
    });
    thumbs.appendChild(item);
    thumbCanvases.push(cv);
  }
  paintThumbs();
}
var thumbRaf = 0;
function paintThumbs() {
  if (thumbRaf) return;
  thumbRaf = requestAnimationFrame(() => {
    thumbRaf = 0;
    thumbCanvases.forEach((cv, i2) => pv.renderThumbnail(i2, cv));
  });
}
pv.addEventListener("us-image", paintThumbs);
document.fonts?.addEventListener?.("loadingdone", paintThumbs);
function updateNav() {
  const n = pv.getSlideCount(), i2 = pv.getSlideIndex();
  $("counter").textContent = n ? `${i2 + 1} / ${n}` : "\u2013";
  $("prev").disabled = !n || i2 === 0;
  $("next").disabled = !n || i2 >= n - 1;
  thumbs.querySelectorAll(".thumb").forEach((el2, k) => el2.classList.toggle("current", k === i2));
  thumbs.children[i2]?.scrollIntoView({ block: "nearest" });
}
pv.addEventListener("us-slide", updateNav);
$("prev").addEventListener("click", () => {
  pv.prev();
  updateNav();
});
$("next").addEventListener("click", () => {
  pv.next();
  updateNav();
});
function present(from) {
  if (!pv.getSlideCount()) return;
  if (playing) {
    pv.stopPlayback();
    endPlay("Reprodu\xE7\xE3o parada");
  }
  pv.present(from, {
    useTimings: $("useTimings").checked,
    loop: $("loop").checked
  });
}
function presentStatus(d) {
  const passos = d.steps ? ` \xB7 passo ${d.step ?? 0}/${d.steps}` : "";
  setStatus(`"${fileName}" \xB7 apresentando slide ${d.index + 1}${passos} \u2014 clique/\u2192 avan\xE7a, \u2190 volta, Esc sai`);
}
$("full").addEventListener("click", () => present(pv.getSlideIndex()));
pv.addEventListener("us-slide", (e) => {
  if (pv.isPresenting()) presentStatus(e.detail);
});
pv.addEventListener("us-step", (e) => presentStatus(e.detail));
pv.addEventListener("us-present-end", () => {
  setStatus("Apresenta\xE7\xE3o encerrada");
  updateNav();
});
function togglePlay() {
  if (!pv.getSlideCount()) return;
  if (playing) {
    pv.stopPlayback();
    return endPlay("Reprodu\xE7\xE3o parada");
  }
  const secs = Math.max(0.5, Number($("defaultSec").value) || 3);
  const tl = pv.play({
    from: pv.getSlideIndex(),
    loop: $("loop").checked,
    useTimings: $("useTimings").checked,
    defaultSlideMs: secs * 1e3
  });
  playing = true;
  playBtn.textContent = "\u25A0 Parar";
  const total = (tl.durationMs / 1e3).toFixed(1).replace(".", ",");
  const tick = () => {
    const t = pv.getPlaybackTime();
    if (t !== null) setStatus(`"${fileName}" \xB7 reproduzindo ${(t / 1e3).toFixed(1).replace(".", ",")} / ${total} s`);
  };
  tick();
  window.clearInterval(clock);
  clock = window.setInterval(tick, 200);
}
var clock = 0;
function endPlay(msg) {
  window.clearInterval(clock);
  playing = false;
  playBtn.textContent = "\u25B6 Reproduzir";
  if (msg) setStatus(msg);
  updateNav();
}
playBtn.addEventListener("click", togglePlay);
pv.addEventListener("us-playback-end", () => endPlay("Reprodu\xE7\xE3o terminou"));
pv.addEventListener("us-slide", () => {
  if (playing && !pv.isPlaying()) endPlay("Reprodu\xE7\xE3o parada");
});
document.addEventListener("keydown", (e) => {
  const t = e.target;
  if (t instanceof HTMLInputElement || t instanceof HTMLSelectElement) return;
  const k = e.key.toLowerCase();
  if (pv.isPresenting()) {
    if (k === "f5") e.preventDefault();
    return;
  }
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  if (k === "f5") {
    present(e.shiftKey ? pv.getSlideIndex() : "start");
    e.preventDefault();
    return;
  }
  if (k === "f") {
    present(pv.getSlideIndex());
    e.preventDefault();
    return;
  }
  if (k === "p") {
    togglePlay();
    e.preventDefault();
    return;
  }
  if (k === "escape" && playing) {
    pv.stopPlayback();
    endPlay("Reprodu\xE7\xE3o parada");
    return;
  }
  if (t === pv) {
    queueMicrotask(updateNav);
    return;
  }
  if (k === "arrowright" || k === "pagedown" || k === " ") {
    pv.next();
    updateNav();
    e.preventDefault();
  } else if (k === "arrowleft" || k === "pageup") {
    pv.prev();
    updateNav();
    e.preventDefault();
  } else if (k === "home") {
    pv.selectSlide(0);
    updateNav();
    e.preventDefault();
  } else if (k === "end") {
    pv.selectSlide(pv.getSlideCount() - 1);
    updateNav();
    e.preventDefault();
  }
});
